Refactor this Go method to avoid holding the read lock while checking expiry:

```go
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	v, ok := c.items[key]
	if !ok || time.Now().After(v.expires) {
		return "", false
	}
	return v.val, true
}
```

